export function pathFilterKey(p,w){return JSON.stringify([p.size,p.path.slice(0,3),p.pathQuality,p.geometryRecords,p.pathCausticTargets,p.pathEnvironment,p.pathLens,p.pathMap,p.pathOptions,p.pathCausticProgress,[...p.pathCaustics.slice(0,2),p.pathCausticProgress?.[1]??p.pathCaustics[2],p.pathCaustics[3]],p.pathDenoise,p.pathFilter.slice(0,2),w.filterVersion,w.environmentBuilds]);}
